import {
    json, hashPassword, verifyPassword, isHashed,
    createSession, destroySession, checkAuth,
    sessionCookie, clearSessionCookie,
    loginLocked, recordLoginFailure, clearLoginFailures, LOGIN_LOCK_SECONDS
} from "./_utils.js";

// POST /api/auth — log in, set an HttpOnly session cookie.
// Repeated failures lock the IP / username out for a while; see the login
// attempt limit in _utils.js.
export async function onRequestPost(context) {
    const { request, env } = context;
    try {
        const { username, password } = await request.json();
        if (!username || !password) {
            return json({ error: "Username and password required" }, 400);
        }

        // Checked before the password, so a locked-out guesser learns nothing
        // even when a guess happens to be right.
        if (await loginLocked(env, request, username)) {
            const minutes = Math.round(LOGIN_LOCK_SECONDS / 60);
            return json(
                { error: `Too many failed login attempts. Try again in ${minutes} minutes.` },
                429,
                { "Retry-After": String(LOGIN_LOCK_SECONDS) }
            );
        }

        const row = await env.DB.prepare(
            "SELECT id, password FROM access_keys WHERE username = ?"
        ).bind(username).first();

        if (!row || !(await verifyPassword(password, row.password))) {
            await recordLoginFailure(env, request, username);
            return json({ error: "Invalid username or password" }, 401);
        }
        await clearLoginFailures(env, request, username);

        // Lazy migration: upgrade a legacy plaintext password to a hash on first
        // successful login, so existing credentials keep working without a bulk migration.
        if (!isHashed(row.password)) {
            const newHash = await hashPassword(password);
            await env.DB.prepare("UPDATE access_keys SET password = ? WHERE id = ?")
                .bind(newHash, row.id).run();
        }

        const token = await createSession(env, row.id);
        return json({ success: true }, 200, { "Set-Cookie": sessionCookie(token, request) });
    } catch (err) {
        return json({ error: "Server error" }, 500);
    }
}

// GET /api/auth — report whether the current session cookie is valid.
export async function onRequestGet(context) {
    const { request, env } = context;
    if (await checkAuth(request, env)) return json({ authenticated: true });
    return json({ authenticated: false }, 401);
}

// DELETE /api/auth — log out (destroy session + clear cookie).
export async function onRequestDelete(context) {
    const { request, env } = context;
    await destroySession(env, request);
    return json({ success: true }, 200, { "Set-Cookie": clearSessionCookie(request) });
}
