// Shared helpers for the CMS API (Cloudflare Pages Functions).
// Ported from the Lipke CMS. Everything is same-origin, so there is no CORS.

export function json(data, status = 200, headers = {}) {
    return new Response(JSON.stringify(data), {
        status,
        headers: { "Content-Type": "application/json", ...headers }
    });
}

export function uuid() {
    return crypto.randomUUID();
}

export function unauthorized() {
    return json({ error: "Unauthorized" }, 401);
}

// ---- Uploads ----
// Only these raster formats are accepted and served as images. SVG is left out
// on purpose: it is a document that can carry script, not just a picture.
export const IMAGE_TYPES = ["image/jpeg", "image/png", "image/webp", "image/gif"];

// The real type of an uploaded file, read from its first bytes. The type the
// browser declares is whatever the uploader says it is, so it decides nothing.
// Returns null for anything that is not one of IMAGE_TYPES.
export async function sniffImageType(file) {
    const b = new Uint8Array(await file.slice(0, 12).arrayBuffer());
    const at = (offset, bytes) => bytes.every((v, i) => b[offset + i] === v);
    if (at(0, [0xFF, 0xD8, 0xFF])) return "image/jpeg";
    if (at(0, [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A])) return "image/png";
    if (at(0, [0x47, 0x49, 0x46, 0x38])) return "image/gif"; // GIF8(7|9)a
    if (at(0, [0x52, 0x49, 0x46, 0x46]) && at(8, [0x57, 0x45, 0x42, 0x50])) return "image/webp"; // RIFF....WEBP
    return null;
}

export const IMAGE_ONLY_MESSAGE = "Only JPEG, PNG, WebP or GIF images can be uploaded.";

// Largest accepted upload. The CMS already shrinks images to well under this
// before sending them, so in practice it only stops oversized files sent to the
// API directly. Keep in step with IMAGE_MAX_BYTES in public/admin/admin.js.
export const MAX_UPLOAD_BYTES = 15 * 1024 * 1024;
export const TOO_LARGE_MESSAGE = "Images must be under 15 MB.";

// A storage key from an uploaded file name: readable, but nothing that needs
// escaping in a URL or could be read as a path.
export function uploadKeyName(name) {
    return (name || "image").replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[.-]+/, "").slice(-80) || "image";
}

// Headers for serving a stored upload. Images keep their type; anything else
// already in a bucket (from before uploads were checked) is sent as a plain
// download. Either way the browser is told not to guess the type and to treat
// the file as an inert, sandboxed resource, so nothing in it can run as a page
// on this domain.
export function uploadResponseHeaders(object) {
    const headers = new Headers();
    object.writeHttpMetadata(headers);
    const type = (headers.get("Content-Type") || "").split(";")[0].trim().toLowerCase();
    if (!IMAGE_TYPES.includes(type)) {
        headers.set("Content-Type", "application/octet-stream");
        headers.set("Content-Disposition", "attachment");
    }
    headers.set("X-Content-Type-Options", "nosniff");
    headers.set("Content-Security-Policy", "default-src 'none'; sandbox");
    headers.set("etag", object.httpEtag);
    headers.set("Cache-Control", "public, max-age=31536000, immutable");
    return headers;
}

// ---- Password hashing (PBKDF2-SHA256) ----
const PBKDF2_ITERATIONS = 100000;

function bufToB64(buf) {
    return btoa(String.fromCharCode(...new Uint8Array(buf)));
}
function b64ToBytes(b64) {
    return Uint8Array.from(atob(b64), c => c.charCodeAt(0));
}

async function deriveBits(password, salt, iterations) {
    const keyMaterial = await crypto.subtle.importKey(
        "raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveBits"]
    );
    return crypto.subtle.deriveBits(
        { name: "PBKDF2", salt, iterations, hash: "SHA-256" },
        keyMaterial, 256
    );
}

export async function hashPassword(password) {
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const bits = await deriveBits(password, salt, PBKDF2_ITERATIONS);
    return `pbkdf2$${PBKDF2_ITERATIONS}$${bufToB64(salt)}$${bufToB64(bits)}`;
}

export function isHashed(stored) {
    return typeof stored === "string" && stored.startsWith("pbkdf2$");
}

export async function verifyPassword(password, stored) {
    if (!isHashed(stored)) {
        return constantTimeEqual(stored ?? "", password); // legacy plaintext
    }
    const [, iterStr, saltB64, hashB64] = stored.split("$");
    const bits = await deriveBits(password, b64ToBytes(saltB64), Number(iterStr));
    return constantTimeEqual(bufToB64(bits), hashB64);
}

function constantTimeEqual(a, b) {
    if (a.length !== b.length) return false;
    let diff = 0;
    for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
    return diff === 0;
}

// ---- Login attempt limit ----
// Failed logins are counted in KV per client IP and per username.
// Reaching either limit refuses further attempts - including correct ones -
// until LOGIN_LOCK_SECONDS have passed without another failure, so guessing a
// password is capped at a handful of tries per quarter hour. A successful
// login clears both counters.
//
// The username limit is higher than the IP one: it is what stops a guesser who
// rotates IP addresses, but it also means someone could lock a real user out
// for 15 minutes by failing on purpose, so it should not trip on an honest
// run of typos.
//
// Counters are keyed by a hash, so neither usernames nor IPs are stored as
// written. KV is eventually consistent: two attempts landing at different
// data centres in the same second may both be counted as the first. That
// slack is fine for this purpose.
export const LOGIN_MAX_FAILS_PER_IP = 5;
export const LOGIN_MAX_FAILS_PER_USER = 10;
export const LOGIN_LOCK_SECONDS = 15 * 60;

async function sha256Hex(text) {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
    return [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, "0")).join("");
}

async function loginFailKeys(request, username) {
    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    const user = String(username || "").trim().toLowerCase();
    return {
        ip: `loginfail:ip:${await sha256Hex(ip)}`,
        user: `loginfail:user:${await sha256Hex(user)}`
    };
}

// Whether this IP or username is currently locked out.
export async function loginLocked(env, request, username) {
    const keys = await loginFailKeys(request, username);
    try {
        const [ipCount, userCount] = await Promise.all([
            env.KV.get(keys.ip), env.KV.get(keys.user)
        ]);
        return Number(ipCount || 0) >= LOGIN_MAX_FAILS_PER_IP ||
               Number(userCount || 0) >= LOGIN_MAX_FAILS_PER_USER;
    } catch (e) {
        return false; // a KV hiccup must not lock everyone out
    }
}

// Count one failed attempt against both the IP and the username. Each failure
// restarts the lock window.
export async function recordLoginFailure(env, request, username) {
    const keys = await loginFailKeys(request, username);
    try {
        const [ipCount, userCount] = await Promise.all([
            env.KV.get(keys.ip), env.KV.get(keys.user)
        ]);
        await Promise.all([
            env.KV.put(keys.ip, String(Number(ipCount || 0) + 1), { expirationTtl: LOGIN_LOCK_SECONDS }),
            env.KV.put(keys.user, String(Number(userCount || 0) + 1), { expirationTtl: LOGIN_LOCK_SECONDS })
        ]);
    } catch (e) {
        /* counting is best effort; the login answer itself does not depend on it */
    }
}

export async function clearLoginFailures(env, request, username) {
    const keys = await loginFailKeys(request, username);
    try {
        await Promise.all([env.KV.delete(keys.ip), env.KV.delete(keys.user)]);
    } catch (e) { /* expires on its own */ }
}

// ---- Sessions (random token stored in KV under session:<token>) ----
const SESSION_TTL = 60 * 60 * 24 * 7; // 7 days

export async function createSession(env, userId) {
    const token = crypto.randomUUID() + crypto.randomUUID().replace(/-/g, "");
    await env.KV.put(`session:${token}`, String(userId), { expirationTtl: SESSION_TTL });
    return token;
}

export function getCookie(request, name) {
    const header = request.headers.get("Cookie") || "";
    for (const part of header.split(";")) {
        const idx = part.indexOf("=");
        if (idx === -1) continue;
        if (part.slice(0, idx).trim() === name) return decodeURIComponent(part.slice(idx + 1).trim());
    }
    return null;
}

export async function getSessionUser(env, request) {
    const token = getCookie(request, "session");
    if (!token) return null;
    return (await env.KV.get(`session:${token}`)) || null;
}

export async function destroySession(env, request) {
    const token = getCookie(request, "session");
    if (token) await env.KV.delete(`session:${token}`);
}

// `Secure` is dropped for localhost so the cookie works over http in local dev.
function secureAttr(request) {
    const host = new URL(request.url).hostname;
    return (host === "localhost" || host === "127.0.0.1") ? "" : " Secure;";
}

export function sessionCookie(token, request) {
    return `session=${token}; HttpOnly;${secureAttr(request)} SameSite=Strict; Path=/; Max-Age=${SESSION_TTL}`;
}

export function clearSessionCookie(request) {
    return `session=; HttpOnly;${secureAttr(request)} SameSite=Strict; Path=/; Max-Age=0`;
}

// Auth guard used by every mutation endpoint — now validates the session cookie.
export async function checkAuth(request, env) {
    return (await getSessionUser(env, request)) !== null;
}

// ---- Content helpers ----

// Trimmed string, or null when empty / not a string.
export const text = v => (typeof v === "string" ? v.trim() : "") || null;

// A JSON-column value from a request body: an array, kept as JSON text.
export function jsonList(value, clean = x => x) {
    return JSON.stringify(Array.isArray(value) ? value.map(clean).filter(Boolean) : []);
}

// A JSON column read back from D1; bad or missing data becomes [].
export function parseList(value) {
    try {
        const parsed = JSON.parse(value || "[]");
        return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
        return [];
    }
}

// GET /api/content (published only) is cached in KV under this key. Every
// mutation clears it; direct D1 edits do not, so clear it by hand after those:
//   npx wrangler kv key delete --binding KV content --remote
export const CONTENT_CACHE_KEY = "content";

export async function invalidateContent(env) {
    try { await env.KV.delete(CONTENT_CACHE_KEY); } catch (e) { /* expires on its own */ }
}
