import { json, checkAuth, unauthorized, invalidateContent } from "../_utils.js";

// DELETE /api/timeline/:id - remove an experience or education entry.
export async function onRequestDelete(context) {
    const { request, env, params } = context;
    if (!await checkAuth(request, env)) return unauthorized();

    try {
        await env.DB.prepare("DELETE FROM timeline WHERE id = ?").bind(params.id).run();
        await invalidateContent(env);
        return json({ success: true });
    } catch (err) {
        return json({ error: err.message }, 500);
    }
}
